-- Synthetic disposable metadata only. No source payload table is needed by the RPC.
alter table connector_accounts add column last_successful_sync_at timestamptz,add column last_failed_sync_at timestamptz;
create table email_accounts(id uuid primary key,tenant_id uuid,provider text,display_name text,status text,auth_state text,last_incremental_success_at timestamptz,last_incremental_attempt_at timestamptz,last_sync_error text);
